package com.mendes.scheduling_platform.availability; import com.mendes.scheduling_platform.exception.*; import com.mendes.scheduling_platform.venue.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AvailabilityService { private final AvailabilityRepository repo; private final VenueRepository venues; public AvailabilityService(AvailabilityRepository r,VenueRepository v){repo=r;venues=v;} public List<Availability> list(Long t,Long venue){venues.findByIdAndTenantId(venue,t).orElseThrow(()->new NotFoundException("Espaço não encontrado"));return repo.findAllByTenantIdAndVenueId(t,venue);} public Availability save(Long t,Long venue,Availability a){if(!a.getStartTime().isBefore(a.getEndTime()))throw new BusinessException("Intervalo inválido");venues.findByIdAndTenantId(venue,t).orElseThrow(()->new NotFoundException("Espaço não encontrado"));a.setId(null);a.setTenantId(t);a.setVenueId(venue);return repo.save(a);} public void delete(Long t,Long id){repo.delete(repo.findByIdAndTenantId(id,t).orElseThrow(()->new NotFoundException("Disponibilidade não encontrada")));} }
